<?php
declare(strict_types=1);
error_reporting(E_ALL); ini_set('display_errors','0');
require_once __DIR__.'/gold_calc_helpers.php';
$currencyDir=dirname(__DIR__).'/currency_data/';$format=strtolower((string)($_GET['format']??'html'));$force=isset($_GET['force']);$slot=getLatest6hSlot();$logFile=getLogFile($slot);$result=(!$force)?readLogRow($logFile,$slot):null;
try {
 if(!$result){$histDT=getPalmierHistoricalDate();$histDate=$histDT->format('Y-m-d');$goldData=loadCsvFull($currencyDir.'XAU_USD.csv');$goldMeta=findRateMeta($goldData,$histDate);if(!$goldMeta)throw new RuntimeException("Missing gold anchor (XAU/USD) for {$histDate}");$goldUSD=(float)$goldMeta['rate'];$currencies=[];$total=0.0;$count=0;
 foreach(glob($currencyDir.'USD_*.csv')?:[] as $file){$ccy=strtoupper(substr(basename($file),4,-4));if($ccy==='')continue;$data=loadCsvFull($file);$meta=findRateMeta($data,$histDate);if(!$meta&&$ccy!=='USD')continue;$rate=$ccy==='USD'?1.0:(float)$meta['rate'];if($rate<=0)continue;$goldPrice=$goldUSD/$rate;$prev=$meta['prev']??null;$next=$meta['next']??null;$currencies[$ccy]=['currency'=>$ccy,'date_used'=>$meta['date_used']??$histDate,'rate'=>$rate,'prev_date'=>$prev['date']??$histDate,'prev_value'=>$prev['value']??$rate,'next_date'=>$next['date']??$histDate,'next_value'=>$next['value']??$rate,'interpolated'=>($meta['type']??'exact')==='interpolated'?'yes':'no','gold_price'=>$goldPrice,'type'=>$meta['type']??'exact'];$total+=$goldPrice;$count++;}
 ksort($currencies,SORT_STRING);$i=1;foreach($currencies as &$row)$row['no']=$i++;unset($row);$result=['timestamp'=>$slot,'generated_at'=>gmdate('Y-m-d\TH:i:s\Z'),'historical_date'=>$histDate,'gold_usd'=>$goldUSD,'historical_currencies_count'=>count($currencies),'historical_gold_average'=>$count?$total/$count:0.0,'currencies'=>$currencies];appendLog($logFile,$result);
 } else { $currencies=$result['currencies']??[];ksort($currencies,SORT_STRING);$i=1;foreach($currencies as &$row)$row['no']=$i++;unset($row);$result['currencies']=$currencies;$result['historical_currencies_count']=count($currencies); }
} catch(Throwable $e){error_log('[PALMIER_GOLD] '.$e->getMessage());http_response_code(500);if($format==='json'||$format==='average'){header('Content-Type: application/json; charset=UTF-8');echo json_encode(['status'=>'error','message'=>'Gold calculation failed. Check server logs and currency data files.']);}else{header('Content-Type: text/plain; charset=UTF-8');echo 'Gold calculation failed. Check server logs and currency data files.';}exit;}
if($format==='json'){header('Content-Type: application/json; charset=UTF-8');echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
if($format==='average'){header('Content-Type: application/json; charset=UTF-8');echo json_encode(['timestamp'=>$result['timestamp'],'historical_gold_average'=>$result['historical_gold_average'],'formatted_average'=>formatPalmierNumber($result['historical_gold_average']),'historical_currencies_count'=>$result['historical_currencies_count']],JSON_PRETTY_PRINT);exit;}
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Palmier Gold Prices</title><style>body{font:14px Arial;margin:24px;color:#222}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #bbb;padding:6px;text-align:right}th:nth-child(2),td:nth-child(2){text-align:left}th{background:#eee}h2{color:#775500}</style></head><body><h2>Palmier Gold Prices</h2><p><b>Slot:</b> <?=$esc($result['timestamp'])?><br><b>Historical Palmier Date:</b> <?=$esc($result['historical_date'])?><br><b>Total Currencies:</b> <?=$esc($result['historical_currencies_count'])?></p><h3>Gold Price in USD: <?=$esc($result['gold_usd'])?></h3><table><thead><tr><th>No.</th><th>Currency</th><th>Date Used</th><th>Rate Used</th><th>Prev Date</th><th>Prev Value</th><th>Next Date</th><th>Next Value</th><th>Interpolated</th><th>Gold Price</th></tr></thead><tbody><?php foreach($result['currencies'] as $ccy=>$c):?><tr><td><?=$esc($c['no'])?></td><td><?=$esc($ccy)?></td><td><?=$esc($c['date_used'])?></td><td><?=$esc($c['rate'])?></td><td><?=$esc($c['prev_date'])?></td><td><?=$esc($c['prev_value'])?></td><td><?=$esc($c['next_date'])?></td><td><?=$esc($c['next_value'])?></td><td><?=$esc($c['interpolated'])?></td><td><b><?=$esc($c['gold_price'])?></b></td></tr><?php endforeach;?><tr><th colspan="9">Average</th><th><?=$esc(formatPalmierNumber($result['historical_gold_average']))?></th></tr></tbody></table><p><a href="?format=json">JSON</a> · <a href="?format=average">Average JSON</a></p></body></html>
